-- ==========================================================
-- CLEAN DATABASE SETUP SCRIPT
-- Wash & Drycleaning System
-- Compatible with current Flask app.py
-- Uses uploaded full sample data
-- ==========================================================

DROP DATABASE IF EXISTS mydb;
CREATE DATABASE mydb;
USE mydb;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS item_types;
DROP TABLE IF EXISTS vendor_deliveries;
DROP TABLE IF EXISTS vendors;
DROP TABLE IF EXISTS system_users;

SET FOREIGN_KEY_CHECKS = 1;

-- ==========================================================
-- TABLES
-- ==========================================================

CREATE TABLE customers (
    customer_id INT AUTO_INCREMENT PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    phone VARCHAR(20) NOT NULL,
    email VARCHAR(100),
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB;

CREATE TABLE item_types (
    item_type_id INT AUTO_INCREMENT PRIMARY KEY,
    item_name VARCHAR(50) NOT NULL,
    base_price DECIMAL(10,2) NOT NULL
) ENGINE = InnoDB;

CREATE TABLE orders (
    order_id INT AUTO_INCREMENT PRIMARY KEY,
    customer_id INT NOT NULL,
    dropoff_date DATE NOT NULL,
    promised_date DATE NOT NULL,
    ready_date DATE NULL,
    pickup_date DATE NULL,
    payment_status VARCHAR(20) NOT NULL,
    order_status VARCHAR(20) NOT NULL,
    total_items INT NOT NULL,
    total_amount DECIMAL(10,2) NOT NULL,
    notes VARCHAR(255),
    CONSTRAINT fk_orders_customers
        FOREIGN KEY (customer_id)
        REFERENCES customers(customer_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE order_items (
    order_item_id INT AUTO_INCREMENT PRIMARY KEY,
    order_id INT NOT NULL,
    item_type_id INT NOT NULL,
    care_type VARCHAR(20) NOT NULL,
    quantity INT NOT NULL,
    unit_price DECIMAL(10,2) NOT NULL,
    line_total DECIMAL(10,2) NOT NULL,
    item_status VARCHAR(20) NOT NULL,
    CONSTRAINT fk_order_items_orders
        FOREIGN KEY (order_id)
        REFERENCES orders(order_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE,
    CONSTRAINT fk_order_items_item_types
        FOREIGN KEY (item_type_id)
        REFERENCES item_types(item_type_id)
        ON DELETE RESTRICT
        ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE vendors (
    vendor_id INT AUTO_INCREMENT PRIMARY KEY,
    vendor_name VARCHAR(100) NOT NULL,
    phone VARCHAR(20),
    category VARCHAR(50) NOT NULL,
    notes VARCHAR(255)
) ENGINE = InnoDB;

-- This table supports BOTH:
-- 1. uploaded sample data, which inserts vendor_id
-- 2. your Flask app, which inserts vendor_name directly
CREATE TABLE vendor_deliveries (
    delivery_id INT AUTO_INCREMENT PRIMARY KEY,
    vendor_id INT NULL,
    vendor_name VARCHAR(100) NULL,
    delivery_date DATE NOT NULL,
    supply_name VARCHAR(100) NOT NULL,
    quantity INT NOT NULL,
    unit_cost DECIMAL(10,2) NOT NULL,
    total_cost DECIMAL(10,2) NOT NULL,
    notes VARCHAR(255),
    CONSTRAINT fk_vendor_deliveries_vendors
        FOREIGN KEY (vendor_id)
        REFERENCES vendors(vendor_id)
        ON DELETE SET NULL
        ON UPDATE CASCADE
) ENGINE = InnoDB;

-- Your app.py also creates cashier/admin users automatically with initialize_users().
-- This table is included so the database is complete before Flask starts.
CREATE TABLE system_users (
    user_id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    user_role VARCHAR(20) NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB;

