-- Fill vendor_name for rows that were inserted using vendor_id.
UPDATE vendor_deliveries vd
JOIN vendors v
    ON vd.vendor_id = v.vendor_id
SET vd.vendor_name = v.vendor_name
WHERE vd.vendor_name IS NULL;

